import re
import pandas as pd
import numpy as np

def parse_amount(val):
    if pd.isna(val) or val == "":
        return np.nan
    val_str = str(val).strip()
    if val_str == "":
        return np.nan

    is_negative = False
    if "CR" in val_str or "(" in val_str or ")" in val_str or "-" in val_str:
        is_negative = True

    val_str = val_str.replace("C1", "").replace("C2", "")
    val_str = re.sub(r'[^0-9,\.]', '', val_str)
    if not val_str:
        return np.nan

    has_comma = ',' in val_str
    has_dot = '.' in val_str

    if has_comma and has_dot:
        last_comma_idx = val_str.rfind(',')
        last_dot_idx = val_str.rfind('.')
        if last_comma_idx > last_dot_idx:
            dec_sep = ','
        else:
            dec_sep = '.'
    elif has_comma and not has_dot:
        last_comma_idx = val_str.rfind(',')
        if len(val_str) - 1 - last_comma_idx == 2:
            dec_sep = ','
        else:
            dec_sep = ''
    elif has_dot and not has_comma:
        last_dot_idx = val_str.rfind('.')
        if len(val_str) - 1 - last_dot_idx == 2:
            dec_sep = '.'
        else:
            dec_sep = ''
    else:
        dec_sep = ''

    if dec_sep == ',':
        last_idx = val_str.rfind(',')
        val_str = val_str[:last_idx].replace(',', '').replace('.', '') + '.' + val_str[last_idx+1:].replace(',', '').replace('.', '')
    elif dec_sep == '.':
        last_idx = val_str.rfind('.')
        val_str = val_str[:last_idx].replace('.', '').replace(',', '') + '.' + val_str[last_idx+1:].replace('.', '').replace(',', '')
    else:
        val_str = val_str.replace(',', '').replace('.', '')

    try:
        num = float(val_str)
    except:
        return np.nan

    if is_negative:
        num = -num
    return num

tests = [
    "1,128", "80,87 C2", "(-81.45)", "105.16", "113 , 61 C2) ", "C1 245.07",
    "124", "43.48 C1", "97,20 C2", "121,43 C2 ", "138.87 C1", "C1 118.59 CR",
    "186.09C1", "128,31 C2", "51", "56 ", "84.64", "(142", "(1,128)"
]

for t in tests:
    print(f"'{t}' -> {parse_amount(t)}")

